// leaf, by what its definition is. Columns and the like have none.
func nodeIcon(n catalog.Node) string {
	switch n.Kind {
	case "schema":
		return "layers"
	case "roles", "memberof", "members":
		return "users"
	case "role":
		return "user"
	case "table", "partitioned":
		return "table-2"
	case "view":
		return "eye"
	case "matview":
		return "box"
	case "columns":
		return "columns-3"
	case "indexes":
		return "list-tree"
	case "constraints":
		return "shield-check"
	case "triggers":
		return "zap"
	case "grants":
		return "key-round"
	case "":
		switch n.Def {
		case "function":
			return "square-function"
		case "sequence":
			return "hash"
		case "type", "domain":
			return "shapes"
		case "collation":
			return "languages"
		case "role":
			return "user"
		}
		return ""
	}
	return "folder"
}

// nodeIconColour picks out the objects you query, over the folders around them.
func nodeIconColour(icon string) string {
	switch icon {
	case "table-2":
		return "text-info"
	case "eye", "box":
		return "text-secondary"
	case "square-function":
		return "text-accent"
	}
	return "text-base-content/50"
}

func treeURL(kind, id string) string {
	return "/tree?" + url.Values{"kind": {kind}, "id": {id}}.Encode()
}

func definitionURL(n catalog.Node) string {
	return "/definition?" + url.Values{"def": {n.Def}, "id": {n.ID}}.Encode()
}

var _ = templruntime.GeneratedTemplate
